/**
 * fixPreparationService — the bridge from a finished investigation to Odito's EXISTING fix workflow. It adds no write path.
 *
 * It does only what the "Create Task" button does today, on the user's behalf and with the same safeguards:
 *   1. Re-derives eligibility on the server (registry + site integration). The model's flag and the stored result are never trusted alone.
 *   2. Finds or creates the Task for (project, issue, page) — the Task model's unique index makes this idempotent and race-safe.
 *   3. Ensures the Task links a Recommendation of the SAME project (generated by the existing recommendation service) because that,
 *      or owner-confirmed typed evidence, is what the existing adapter writes. Investigation text/code is NEVER written to a site.
 *
 * Applying stays where it is: POST /tasks/:id/apply-wordpress, which refuses unless `approved === true`, the caller owns the task's
 * project, the status transition is valid, and a same-project recommendation is linked (wordPressSeoFixService.applyFix).
 * Verification stays with TaskVerificationService / startUrlVerification.
 */

import mongoose from 'mongoose';
import Task from '../../tasks/model/Task.js';
import { captureIssueContext } from '../../tasks/service/taskIssueContext.js';
import recommendationService from '../../recommendations/service/recommendationService.js';
import { ELIGIBILITY } from '../capabilities/fixCapabilities.js';

export class FixPreparationError extends Error {
  constructor(code, message, statusCode = 422, details = null) { super(message); this.name = 'FixPreparationError'; this.code = code; this.statusCode = statusCode; this.details = details; }
}

const FIXABLE_STATUS = ['confirmed', 'partially_present'];
const isDup = (e) => e && (e.code === 11000 || /E11000/.test(e.message || ''));

/**
 * @param {{ investigation: object, project: { id: string }, userId: string }} args
 * @param {object} [deps] injectable for tests
 */
export async function prepareFix({ investigation, project, userId }, deps = {}) {
  const {
    resolveCapabilities, loadConfirmedAddress = async () => null, TaskModel = Task, capture = captureIssueContext, generateRecommendation = (p) => recommendationService.getOrGenerate(p),
  } = deps;
  if (!investigation || String(investigation.projectId) !== String(project.id)) throw new FixPreparationError('NOT_FOUND', 'Investigation not found.', 404);

  const r = investigation.result;
  if (investigation.status !== 'completed' || !r) throw new FixPreparationError('INVESTIGATION_NOT_COMPLETE', 'The investigation has not finished.', 409);
  if (!FIXABLE_STATUS.includes(r.issueStatus)) {
    throw new FixPreparationError('ISSUE_NOT_CONFIRMED', 'The investigation did not confirm this issue on the live page, so there is nothing to apply.', 422, { issueStatus: r.issueStatus });
  }
  // Only a PUBLISHABLE proposal can be prepared. Blocked / awaiting-information results get their blockers back, with the manual plan.
  const pState = r.proposalState?.status;
  if (pState && pState !== 'publishable') {
    throw new FixPreparationError('PROPOSAL_NOT_PUBLISHABLE', `There is no publishable change yet (${pState.replace(/_/g, ' ')}): ${(r.blockers || []).map((b) => b.code).join(', ') || 'see the blockers'}.`, 422, { proposalState: pState, blockers: r.blockers || [], manualPlan: r.implementationPlan || [] });
  }
  // A proposal built from a user-confirmed address is valid only while that confirmation is unchanged (same address, same website).
  const bnd = r.proposal?.bindings || {};
  if (bnd.addressStatus === 'confirmed_by_owner') {
    const confirmed = await loadConfirmedAddress(String(project.id)).catch(() => null);
    if (!confirmed || confirmed.addressHash !== bnd.addressHash) throw new FixPreparationError('ADDRESS_CHANGED', 'The confirmed address changed (or is gone) since this proposal was built. Re-run the investigation.', 409);
  }
  // The stored claim must have passed the contract's checks AND the server must agree right now (the site's connection may have changed).
  const capabilities = await resolveCapabilities({ issueId: investigation.issueId, projectId: project.id, operation: r.proposalState?.operation || undefined });
  if (!r.automaticFixEligibility?.eligible || capabilities.eligibility !== ELIGIBILITY.ELIGIBLE) {
    throw new FixPreparationError('NOT_ELIGIBLE', capabilities.eligibility === ELIGIBILITY.ELIGIBLE
      ? 'This proposal did not pass every safety check, so it must be applied manually.'
      : capabilities.reason, 422, { eligibility: capabilities.eligibility, missingCapabilities: capabilities.missingCapabilities, manualPlan: r.implementationPlan || [] });
  }

  const pid = new mongoose.Types.ObjectId(String(project.id));
  const key = { projectId: pid, issueKey: investigation.issueId, pageUrl: investigation.pageUrl };

  let task = await TaskModel.findOne(key);
  let createdTask = false;
  if (!task) {
    const meta = investigation.issueMeta || {};
    const data = {
      ...key, issueName: meta.title || investigation.issueId, issueCategory: meta.category || '', status: 'task_created', origin: 'ai_fix', createdBy: userId || null,
    };
    const issueContext = await capture(pid, investigation.issueId, investigation.pageUrl);
    if (issueContext) data.issueContext = issueContext;
    try { task = await TaskModel.create(data); createdTask = true; }
    catch (e) { if (isDup(e)) task = await TaskModel.findOne(key); else throw e; }
  }
  if (!task || task.isDeleted) throw new FixPreparationError('TASK_UNAVAILABLE', 'The task for this issue was removed. Restore or recreate it from the issue list.', 409);

  let recommendationLinked = !!task.recommendationId;
  if (!recommendationLinked) {
    if (!['task_created', 'reopened'].includes(task.status)) {
      throw new FixPreparationError('TASK_STATE_CONFLICT', `The task is already ${task.status}; nothing to prepare.`, 409, { taskStatus: task.status });
    }
    let generated;
    try {
      generated = await generateRecommendation({
        projectId: String(project.id), issueId: investigation.issueId, pageUrl: investigation.pageUrl,
        issueSource: investigation.issueMeta?.issueSource || 'on_page', ruleMetadata: { title: investigation.issueMeta?.title, description: investigation.issueMeta?.description, category: investigation.issueMeta?.category, severity: investigation.issueMeta?.severity },
      });
    } catch (e) {
      if (e?.userFacing) throw new FixPreparationError(e.code || 'RECOMMENDATION_REFUSED', e.message, e.statusCode || 422);
      throw new FixPreparationError('RECOMMENDATION_FAILED', 'The recommendation needed for the fix could not be generated. Try again.', 502);
    }
    const recId = generated?.recommendation?.id;
    if (!recId) throw new FixPreparationError('RECOMMENDATION_FAILED', 'No recommendation was produced for this issue.', 502);
    // Conditional write: never replace a recommendation another request linked in the meantime.
    const upd = await TaskModel.updateOne({ _id: task._id, projectId: pid, recommendationId: null, status: { $in: ['task_created', 'reopened'] } }, { $set: { recommendationId: new mongoose.Types.ObjectId(String(recId)) } });
    task = await TaskModel.findOne(key);
    recommendationLinked = !!task?.recommendationId;
    if (!recommendationLinked) throw new FixPreparationError('TASK_STATE_CONFLICT', 'The task changed while it was being prepared. Refresh and try again.', 409, { modified: upd?.modifiedCount ?? 0 });
  }

  // Bind the task to THIS investigation's proposal. A different (older) binding is replaced only while the task has not been implemented;
  // re-binding resets nothing else, and an approval given to the old proposal simply does not match the new fingerprint.
  const binding = { investigationId: String(investigation._id), fingerprint: investigation.result.proposal?.fingerprint || null, recommendationId: String(task.recommendationId), boundAt: new Date() };
  if (!binding.fingerprint) throw new FixPreparationError('PROPOSAL_MISSING', 'The investigation has no bound proposal; run it again.', 409);
  const sameBinding = task.investigationBinding && String(task.investigationBinding.investigationId) === binding.investigationId && task.investigationBinding.fingerprint === binding.fingerprint && String(task.investigationBinding.recommendationId) === binding.recommendationId;
  if (!sameBinding) {
    const bound = await TaskModel.updateOne({ _id: task._id, projectId: pid, status: { $in: ['task_created', 'reopened'] } }, { $set: { investigationBinding: binding } });
    if (!bound.modifiedCount && !bound.matchedCount) throw new FixPreparationError('TASK_STATE_CONFLICT', 'The task is no longer open for a new fix; refresh and try again.', 409);
    task = await TaskModel.findOne(key);
  }

  return {
    taskId: String(task._id), taskStatus: task.status, createdTask, recommendationId: String(task.recommendationId), proposalFingerprint: binding.fingerprint,
    adapterId: capabilities.adapterId, field: capabilities.field,
    // The approval step is the existing one; the backend refuses to write unless the caller sends approved:true.
    next: { action: 'approve_then_apply_via_existing_workflow', approvalRequired: true, approveEndpoint: `/recommendations/investigations/${investigation._id}/approve`, endpoint: `/tasks/${task._id}/apply-wordpress` },
  };
}

export default { prepareFix, FixPreparationError };
